const ecosystemOld={resident:planResident,animal:planAnimal,labor:laborPlan,simulate,newWorld,restore,selection:showSelection,renderKingdoms,prey:suitablePrey,drawCreature,animalBirth:registerAnimalBirth,icon:makeControlIcon};
const wildlifeDefs={deer:{name:'Hươu',kind:'sheep',period:'holocene',pace:1.05,habitats:['plains','taiga','jungle'],color:'#ba8859',icon:'🦌',size:1.65},rabbit:{name:'Thỏ',kind:'sheep',period:'holocene',pace:1.2,habitats:['plains','taiga'],color:'#c1a582',icon:'🐇',size:.95},fox:{name:'Cáo',kind:'wolf',period:'holocene',pace:1.1,habitats:['plains','taiga','jungle'],color:'#de8b48',icon:'🦊',size:1.25}};
Object.assign(ancientDefs,wildlifeDefs);
for(const [key,d] of Object.entries(wildlifeDefs)){groups.life.push(['ancient-'+key,d.icon,d.name,key==='fox'?'Cáo hoạt động ban đêm, săn thỏ; nghỉ ban ngày.':key==='rabbit'?'Thỏ kiếm ăn lúc chiều tối; con non theo bố mẹ.':'Hươu sống theo đàn, kiếm ăn lúc bình minh và chiều.']);if(typeof iconCatalog!=='undefined')iconCatalog['ancient-'+key]={file:'ecosystem-sprites-v1.png',index:Object.keys(wildlifeDefs).indexOf(key),columns:3};}
const ecosystemSprite=new Image();let ecosystemSpriteReady=false;
// NEW: crop complete silhouettes once; generated artwork does not fall exactly on cell boundaries.
ecosystemSprite.onload=()=>{const boxes=[[45,45,580,530],[610,230,925,535],[955,155,1515,535],[40,575,545,975],[605,705,930,975],[1020,615,1520,985]],sheet=document.createElement('canvas');sheet.width=192;sheet.height=128;const c=sheet.getContext('2d');for(let n=0;n<6;n++){const [x,y,right,bottom]=boxes[n],width=right-x,height=bottom-y,scale=54/Math.max(width,height);c.drawImage(ecosystemSprite,x,y,width,height,n%3*64+(64-width*scale)/2,Math.floor(n/3)*64+58-height*scale,width*scale,height*scale);}preparedArt.set(ecosystemSprite,{sheet,cell:64,rows:2});ecosystemSpriteReady=true;mapDirty=true;if(tab==='life')renderTools();};ecosystemSprite.src='assets/ecosystem-sprites-v1.png';
let householdTick=0,censusTick=0,wildBirthTick=0;
const realmCensus=new Map(),settlementCensus=new Map();
function householdFor(e){return e.family??={partnerId:null,due:0,fatherId:null,nextBirthAt:simTime+60};}
function occupiedHome(id){return humans().filter(p=>p.hp>0&&lifeFor(p).homeId===id);}
function updateCensus(){realmCensus.clear();settlementCensus.clear();for(const e of humans()){if(e.hp<=0)continue;settlementCensus.set(e.village,(settlementCensus.get(e.village)||0)+1);const id=kingdomOf(e);realmCensus.set(id,(realmCensus.get(id)||0)+1);}}
function realmPopulationLabel(v){return v.name+' · '+(realmCensus.get(v.kingdom)||0)+' người';}
// Construction can receive help from two adult residents even without a dedicated builder.
laborPlan=function(e,v){if(v?.housePlan&&e.age>=16&&!e.soldier){const workers=humans().filter(p=>p.village===v.id&&p.age>=16&&!p.soldier).sort((a,b)=>(b.job==='builder')-(a.job==='builder')||a.id-b.id);if(workers.slice(0,2).includes(e)&&lifeFor(e).load===0){lifeFor(e).targetIndex=idx(v.housePlan.x,v.housePlan.y);taskMove(e,{x:v.housePlan.x,y:v.housePlan.y+.25},'build');return true;}}return ecosystemOld.labor(e,v);};
planResident=function(e){if(e.id===possessed)return ecosystemOld.resident(e);const h=residentHome(e),hour=readCalendar().hour,l=lifeFor(e),fire=laws.disasters?burningNear(e):null,enemy=around(e,5,p=>hungryPredator(p)&&suitablePrey(p,e)||p.kind==='human'&&atWar(kingdomOf(e),kingdomOf(p)))[0];
 if(!fire&&!enemy&&(hour>=19||hour<6)){const v=villages.find(v=>v.id===e.village);e.activity=hour>=20||hour<6?'sleeping':'resting';if(h&&!(e.hunger<15&&!v?.food)&&!(e.thirst<15&&!v?.water)){enterHome(e,h,e.activity==='sleeping'?'sleep':'rest');return;}if(e.hunger>=15&&e.thirst>=15){const refuge=v&&walkable(v.x,v.y)?v:l.den;if(Math.hypot(e.x-refuge.x,e.y-refuge.y)>1.5){l.action='walk';go(e,refuge,'home',20);}else{l.inside=false;l.action='rest';pauseAnimal(e,'rest',3);}return;}}
 ecosystemOld.resident(e);
};
function serveHomeMeals(dt){for(const e of humans()){if(!isResidentIndoors(e)){if(['sleep','rest'].includes(lifeFor(e).action))e.energy=Math.min(100,e.energy+dt*.08);continue;}const v=villages.find(v=>v.id===e.village);if(!v)continue;if(e.hunger<80&&v.food>0){const amount=Math.min(v.food,dt*.5,(80-e.hunger)/10);v.food-=amount;e.hunger+=amount*10;}if(e.thirst<85&&v.water>0){const amount=Math.min(v.water,dt*.5,(85-e.thirst)/10);v.water-=amount;e.thirst+=amount*10;}}}
function healthyParent(e){return e.hp>65&&e.hunger>65&&e.thirst>45&&e.age>=18&&e.age<60&&!e.plague;}
function reuniteHouseholds(){for(const e of humans()){const partner=entities.find(p=>p.id===householdFor(e).partnerId);if(!partner||partner.village!==e.village||e.id>partner.id)continue;const current=residentHome(e),other=residentHome(partner);if(current===other&&current&&occupiedHome(current.id).every(p=>p===e||p===partner||p.parents.includes(e.id)||p.parents.includes(partner.id)))continue;const home=houses.find(h=>h.hp>0&&h.village===e.village&&walkable(h.x,h.y)&&!grid[idx(h.x,h.y)].fire&&occupiedHome(h.id).every(p=>p===e||p===partner));if(!home)continue;if((clearRoute(e,homeDoor(home))||pathStep(e,homeDoor(home),false))&&(clearRoute(partner,homeDoor(home))||pathStep(partner,homeDoor(home),false)))for(const p of [e,partner]){lifeFor(p).homeId=home.id;leaveHome(p);}}}
function pairHouseholds(){const people=humans();for(const e of people){const f=householdFor(e),partner=people.find(p=>p.id===f.partnerId);if(f.partnerId&&(!partner||partner.village!==e.village||partner.hp<=0)){f.partnerId=null;f.due=0;f.fatherId=null;}if(f.partnerId||e.sex!=='a'||!healthyParent(e))continue;const other=people.find(p=>p.id!==e.id&&p.village===e.village&&p.race===e.race&&p.sex==='b'&&healthyParent(p)&&!householdFor(p).partnerId&&!e.parents.includes(p.id)&&!p.parents.includes(e.id)&&!e.parents.some(id=>p.parents.includes(id)));if(!other)continue;const home=houses.find(h=>h.hp>0&&h.village===e.village&&walkable(h.x,h.y)&&!grid[idx(h.x,h.y)].fire&&occupiedHome(h.id).filter(p=>p!==e&&p!==other).length<=1);if(!home)continue;if(!clearRoute(e,homeDoor(home))&&!pathStep(e,homeDoor(home),false))continue;if(!clearRoute(other,homeDoor(home))&&!pathStep(other,homeDoor(home),false))continue;f.partnerId=other.id;householdFor(other).partnerId=e.id;for(const p of [e,other]){lifeFor(p).homeId=home.id;leaveHome(p);}}}
function familyBirthStep(){if(!laws.births)return;pairHouseholds();reuniteHouseholds();for(const mother of humans()){const f=householdFor(mother);if(mother.sex!=='a'||!f.partnerId)continue;const father=entities.find(p=>p.id===f.partnerId),v=villages.find(v=>v.id===mother.village),home=residentHome(mother);if(!father||!v||!home||father.village!==mother.village||lifeFor(father).homeId!==home.id)continue;const pop=settlementCensus.get(v.id)||0,safe=!wars.some(w=>w.a===v.kingdom||w.b===v.kingdom)&&!grid[idx(home.x,home.y)].fire&&v.food>Math.max(24,pop*3)&&v.water>10&&occupiedHome(home.id).length<3;
 if(!safe||!healthyParent(mother)||!healthyParent(father))continue;
 if(!f.due){if(simTime<f.nextBirthAt)continue;f.due=simTime+GAME_DAY_SECONDS*.25;f.fatherId=father.id;continue;}
 if(simTime<f.due||f.fatherId!==father.id||entities.length>=350)continue;
 const wasBirth=birthContext;let child;try{birthContext=true;const door=homeDoor(home);child=spawn('human',door.x,door.y,v.id);}finally{birthContext=wasBirth;}if(!child)continue;child.age=0;child.race=mother.race;child.parents=[mother.id,father.id];child.generation=Math.max(mother.generation,father.generation)+1;child.traits=[...mother.traits.filter(t=>!['blessed','cursed'].includes(t)).slice(0,1)];child.soldier=false;child.hunger=90;child.thirst=90;child.bornAt=simTime;lifeFor(child).homeId=home.id;lifeFor(child).parentId=mother.id;householdFor(child);if(isResidentIndoors(mother)){lifeFor(child).inside=true;lifeFor(child).action='sleep';child.activity='sleeping';}v.food-=12;f.due=0;f.fatherId=null;f.nextBirthAt=simTime+GAME_DAY_SECONDS;householdFor(father).nextBirthAt=f.nextBirthAt;remember('Một em bé chào đời tại '+v.name+' · Bố mẹ: '+mother.name+' và '+father.name+'.','civil');updateCensus();}}
// Species-specific prey and clocks; emergency needs and predators always interrupt rest.
suitablePrey=function(hunter,prey){if(hunter.species==='fox')return prey.species==='rabbit'||prey.kind==='sheep'&&prey.age<1;if(['deer','rabbit'].includes(prey.species))return hunter.kind==='wolf';return ecosystemOld.prey(hunter,prey);};
function wildlifeRest(e,type){const l=lifeFor(e);const m=mindFor(e);m.prey=null;let den=l.den;if(!den||!walkable(den.x,den.y)||grid[idx(den.x,den.y)].fire||Math.hypot(e.x-den.x,e.y-den.y)>9){den={x:e.x,y:e.y};l.den=den;}if(Math.hypot(e.x-den.x,e.y-den.y)>1&&clearRoute(e,den)){go(e,den,'den',15);l.action='walk';return;}pauseAnimal(e,type,4);l.action=type;}
planAnimal=function(e){if(e.id===possessed)return ecosystemOld.animal(e);const l=lifeFor(e),hour=readCalendar().hour,fire=laws.disasters?burningNear(e):null,enemy=e.kind==='sheep'?around(e,7,p=>hungryPredator(p)&&suitablePrey(p,e))[0]:null;
 if(fire||enemy)return ecosystemOld.animal(e);
 const inactive=e.species==='fox'?hour>=7&&hour<19:e.species==='rabbit'?hour>=9&&hour<17:e.species==='deer'?!(hour>=5&&hour<10||hour>=16&&hour<21):e.kind==='sheep'?hour>=20||hour<6:e.kind==='wolf'?hour>=9&&hour<17:false;
 if(inactive&&e.hunger>25&&l.thirst>20){wildlifeRest(e,e.species==='deer'&&hour>=10&&hour<16?'rest':'sleep');return;}
 ecosystemOld.animal(e);
};
function animalBirthEligible(e){return laws.births&&e.age>=1&&!(e.juvenileUntil>simTime)&&e.hp>65&&lifeFor(e).thirst>45&&around(e,5,p=>p.kind===e.kind&&(p.species||'')===(e.species||'')&&p.sex!==e.sex&&p.age>=1&&!(p.juvenileUntil>simTime)&&p.hp>65&&p.hunger>65).length>0&&entities.filter(p=>(p.species||p.kind)===(e.species||e.kind)).length<(e.species==='rabbit'?24:e.species==='deer'?18:40);}
registerAnimalBirth=function(parent,child){ecosystemOld.animalBirth(parent,child);if(child){child.bornAt=simTime;child.juvenileUntil=simTime+GAME_DAY_SECONDS;child.cooldown=GAME_DAY_SECONDS*.5;lifeFor(child).den={...lifeFor(parent).den};const mate=around(parent,5,p=>p.kind===parent.kind&&p.species===parent.species&&p.sex!==parent.sex&&p.age>=1)[0];child.parents=mate?[parent.id,mate.id]:[parent.id];}};
function seedEcosystem(){for(const [species,d] of Object.entries(wildlifeDefs)){const desired=species==='fox'?3:species==='rabbit'?8:6,count=entities.filter(e=>e.species===species).length;for(let n=count;n<desired;n++){let point;for(let k=0;k<N;k++){const i=(n*881+k*17+Object.keys(wildlifeDefs).indexOf(species)*1229)%N,x=i%W+.5,y=Math.floor(i/W)+.5;if(walkable(x,y)&&grid[i].obj===-1&&!grid[i].fire&&d.habitats.includes(biomeAt(x,y))&&villages.every(v=>Math.hypot(v.x-x,v.y-y)>8)){point={x,y};break;}}if(point){const e=spawnAncient(species,point.x,point.y);if(e){e.sex=n%2?'a':'b';lifeFor(e).den=point;}}}}indexResidents();}
function renderEcosystemStatus(){const box=$('ecosystem-status');if(!box)return;const people=humans(),homeless=people.filter(e=>!residentHome(e)).length;box.textContent='🏠 '+houses.filter(h=>h.hp>0).length+' nhà · tối đa 3 người/nhà · '+homeless+' người chưa có nhà\n👶 '+people.filter(e=>e.age<16).length+' trẻ em · '+people.filter(e=>e.family?.due>0).length+' gia đình đang chờ em bé\n'+Object.entries(wildlifeDefs).map(([key,d])=>d.icon+' '+d.name+': '+entities.filter(e=>e.species===key).length).join(' · ');}
simulate=function(dt){ecosystemOld.simulate(dt);serveHomeMeals(dt);householdTick+=dt;censusTick+=dt;wildBirthTick+=dt;if(householdTick>=10){householdTick%=10;familyBirthStep();}if(wildBirthTick>=20){wildBirthTick%=20;for(const e of entities.slice()){if(e.kind==='human')continue;if(e.juvenileUntil&&e.juvenileUntil<=simTime){e.age=Math.max(1,e.age);delete e.juvenileUntil;}if(e.species==='fox'&&e.sex==='a'&&simTime>=(e.nextWildBirth||0)&&animalBirthEligible(e)&&entities.filter(p=>p.species==='fox').length<8){const was=birthContext;let child;try{birthContext=true;child=spawnAncient('fox',e.x,e.y);}finally{birthContext=was;}if(child){registerAnimalBirth(e,child);e.hunger-=15;e.nextWildBirth=simTime+GAME_DAY_SECONDS;}}}}if(censusTick>=1){censusTick%=1;updateCensus();renderEcosystemStatus();}};
function resetEcosystem(seedAnimals){householdTick=censusTick=wildBirthTick=0;for(const e of humans())householdFor(e);assignHomes();if(seedAnimals)seedEcosystem();updateCensus();renderEcosystemStatus();}
newWorld=function(...args){ecosystemOld.newWorld(...args);resetEcosystem(true);};
restore=function(input){const d=JSON.parse(JSON.stringify(input));if(!d?.entities?.every(e=>e.family===undefined||e.family&&[e.family.due,e.family.nextBirthAt].every(n=>Number.isFinite(n)&&n>=0&&n<=1e9)&&[e.family.partnerId,e.family.fatherId].every(n=>n===null||Number.isInteger(n)&&n>0)))throw Error('Dữ liệu gia đình không hợp lệ.');ecosystemOld.restore(d);resetEcosystem(false);};
drawCreature=function(e,bob){const def=wildlifeDefs[e.species];if(!def||!ecosystemSpriteReady)return ecosystemOld.drawCreature(e,bob);const sleeping=['sleep','rest'].includes(lifeFor(e).action),n=Object.keys(wildlifeDefs).indexOf(e.species)+(sleeping?3:0),size=def.size*(e.juvenileUntil>simTime?.65:1),m=motionFor(e);ctx.save();ctx.translate(e.x,e.y+(sleeping?0:bob));ctx.scale(m.facing<0?-1:1,1);atlasTo(ctx,ecosystemSprite,n,3,0,0,size);ctx.restore();};
makeControlIcon=function(key){const d=wildlifeDefs[key.replace('ancient-','')];if(!d||!ecosystemSpriteReady)return ecosystemOld.icon(key);const span=document.createElement('span'),art=prepareAtlas(ecosystemSprite,3);span.className='item-picture atlas-picture';art.url??=art.sheet.toDataURL();span.style.backgroundImage='url("'+art.url+'")';span.style.backgroundSize='300% 200%';span.style.backgroundPosition=(Object.keys(wildlifeDefs).indexOf(key.slice(8))*50)+'% 0%';span.setAttribute('aria-hidden','true');return span;};
showSelection=function(id){ecosystemOld.selection(id);const e=entities.find(e=>e.id===id);if(!e)return;const p=document.createElement('p');if(e.kind==='human'){const partner=entities.find(p=>p.id===householdFor(e).partnerId),home=residentHome(e);p.textContent=(home?'🏠 Nhà '+home.id+' · '+occupiedHome(home.id).length+'/3 người':'Chưa có nhà')+(partner?' · Gia đình với '+partner.name:'')+(e.family.due?' · Đang chờ em bé':'')+(e.parents.length?' · Bố mẹ: '+e.parents.map(id=>entities.find(p=>p.id===id)?.name||'đã mất').join(', '):'');}else{p.textContent=wildlifeDefs[e.species]?.name+' · '+(purposeNames[lifeFor(e).action]||'Đi lại');if(!wildlifeDefs[e.species])return;}$('selection').append(p);};
renderKingdoms=function(){ecosystemOld.renderKingdoms();for(const k of kingdoms){const people=members(k.id),lands=new Set(villages.filter(v=>v.kingdom===k.id).map(v=>v.id)),homes=houses.filter(h=>h.hp>0&&lands.has(h.village));if(!people.length)continue;const p=document.createElement('p');p.className='kingdom-detail';p.textContent=k.name+' · '+people.length+' người · '+people.filter(e=>e.age<16).length+' trẻ em · '+homes.length+' nhà / '+homes.length*3+' chỗ · '+people.filter(e=>!residentHome(e)).length+' người đang chờ nhà';$('kingdom-list').append(p);}};
const ecologyPanel=document.createElement('p');ecologyPanel.id='ecosystem-status';ecologyPanel.style.cssText='white-space:pre-line;font-size:12px;line-height:1.8;color:#a6c8b7;padding:12px;background:#172a2b;border-radius:8px';document.querySelector('.info')?.append(ecologyPanel);
resetEcosystem(true);if(tab==='life')renderTools();
window.mamWorld={...window.mamWorld,newWorld:(...a)=>newWorld(...a),simulate:dt=>simulate(dt),restore:d=>restore(d),getEcosystem:()=>({kingdoms:kingdoms.map(k=>({id:k.id,name:k.name,population:realmCensus.get(k.id)||0})),houseCapacity:3,homeless:humans().filter(e=>!residentHome(e)).length,pregnancies:humans().filter(e=>e.family?.due>0).length,species:Object.keys(wildlifeDefs).map(species=>({species,count:entities.filter(e=>e.species===species).length}))})};
